5:function apply(operator, left, right) {
6:  left = Number(left);
7:  right = Number(right);
8:  const value = operator.value;
9:  if ((value === '/' || value === '//' || value === '%') && right === 0) {
10:    throw new ExprError('Division by zero', operator.column);
11:  }
12:  switch (value) {
13:    case '+': return left + right;
14:    case '-': return left - right;
15:    case '*': return left * right;
16:    case '/': return left / right;
17:    case '**': return left ** right;
18:    case '//': {
19:      const quotient = Math.trunc(left / right);
20:      return quotient === 0 ? 0 : quotient;
21:    }
22:    case '%': {
23:      const remainder = left % right;
24:      if (remainder === 0) return 0;
25:      return remainder;
26:    }
27:    case '<': return left < right;
28:    case '<=': return left <= right;
29:    case '>': return left > right;
30:    case '>=': return left >= right;
31:    case '==': return left === right;
32:    case '!=': return left !== right;
33:    default: throw new Error('Invalid AST operator');
34:  }
35:}
