37:/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
38:function evaluateAst(root, variables) {
39:  const frames = [{ node: root, phase: 0 }];
40:  let result;
41:  while (frames.length) {
42:    const frame = frames[frames.length - 1];
43:    const node = frame.node;
44:    if (node.type === 'number') {
45:      result = node.value;
46:      frames.pop();
47:    } else if (node.type === 'variable') {
48:      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
49:        throw new ExprError('Unknown variable', node.column);
50:      }
51:      result = variables[node.name];
52:      frames.pop();
53:    } else if (node.type === 'unary') {
54:      if (frame.phase === 0) {
55:        frame.phase = 1;
56:        frames.push({ node: node.operand, phase: 0 });
57:      } else {
58:        result = node.operator.value === '-' ? -Number(result) : Number(result);
59:        frames.pop();
60:      }
61:    } else if (node.type === 'binary') {
62:      if (frame.phase === 0) {
63:        frame.phase = 1;
64:        frames.push({ node: node.left, phase: 0 });
65:      } else if (frame.phase === 1) {
66:        frame.left = result;
67:        frame.phase = 2;
68:        frames.push({ node: node.right, phase: 0 });
69:      } else {
70:        result = apply(node.operator, frame.left, result);
71:        frames.pop();
72:      }
73:    } else if (node.type === 'comparison') {
74:      if (frame.phase === 0) {
